window.POETRY_REGISTER("v5-strict-11-9-0-57755845e9be.js",{"poems":[[3356,2],[86482,7],[96418,7],[104970,7],[105084,7],[121767,7],[126369,7],[126976,7],[136924,7],[187748,7],[187906,7],[199273,7],[207318,7],[215148,7],[225267,7],[227406,7],[227410,7],[233405,7],[238527,7],[240866,7],[250738,7],[260174,7],[262739,7],[266727,7],[267609,7],[271711,7],[272068,7],[272337,7],[272338,7],[272346,7],[272372,7],[286023,7],[286092,7],[287671,7],[287932,7],[287951,7],[288124,7],[288125,7],[288137,7],[290727,7],[297109,7],[297987,7],[306895,7],[309602,7],[310484,7],[313560,7],[320871,7],[321250,7],[321255,7],[322552,7],[324593,7],[340214,9],[340922,9],[341125,9],[346429,9],[346430,9],[350250,9],[350997,9],[350999,9],[352543,9],[353495,9],[360403,9],[368191,10],[368689,10],[371067,10],[374755,10],[374757,10],[374760,10],[380144,10],[382197,0],[391198,13],[391498,13],[395317,13],[398414,13],[411684,8],[415442,8],[415447,8],[416495,8],[425774,8],[436482,8],[436697,8],[438246,8],[446568,8],[447505,8],[447767,8],[450139,8],[452823,8],[453877,8],[460795,8],[462372,8],[465479,8],[467728,8],[471427,8],[473778,8],[488561,8],[493194,8],[495465,8],[495517,8],[499907,8],[502767,8],[507883,8],[509931,8],[512275,8],[542007,8],[552499,8],[566073,8],[575736,8],[581832,8],[593364,8],[608077,8],[614594,8],[646991,15],[647433,15],[650074,5],[651338,5],[652758,5],[657023,5],[658913,5],[659098,5],[659970,5],[660615,5],[667928,5],[668536,5],[668790,5],[669762,5],[670224,5],[670242,5],[670602,5],[670772,5],[671259,5],[671599,5],[676096,5],[680916,5],[681117,5],[681637,5],[681805,5],[690414,5],[703969,5],[705466,5],[706856,5],[707016,5],[707096,5],[708914,5],[730128,5],[734722,5],[736369,19],[739416,20]],"pairs":[["朝不日出兮夜不见月与星","有知无知兮为死为生",0],["是知不义之富贵如浮云兮","惟道德为性命之要枢",1],["但见丹霞翠壁远近映楼阁","晨钟暮鼓杳霭罗幡幢",2],["予恐世人不知嵩丘岩洞中","中有八万二千修月户",3],["果然人言所出山芋为第一","西南诸郡有者皆虚名",4],["奸邪缩手不敢更侮祖宗法","又荐处士博士登石渠",5],["苍天苍天能令南溪迹成古","不信收得诗名和迹去",6],["何时茅檐归去炙背读文字","遣儿折取枯竹女煎汤",7],["工师告余曰斯不可以为珮","弃捐椟中兮三岁不会",8],["庶揖让以敉宁兮传诸罔极","世不乏圣兮惟皇与直",9],["使五老奉觞上寿以申祝兮","令夫八元夹侍而正仪",10],["得非道者庵边隔世植万本","伦魁飞来排斡予交樛",11],["当时丹气蒸山一乡植物茂","丹液入根独此偃盖稠",11],["古来惟有竹林诸人称达生","一醉之外万事鸿毛轻",12],["后来又写越影超光脱丹碧","后来又写汉武穷渥洼",13],["我时醉卧洞庭之北巴山东","耳边澒洞呼汹怖杀侬",14],["君视八纮兮昔何殊于弃屣","今复何有兮一席之壝",15],["我黍我稌兮抑亦荐其萍芹","君明其衷兮无吐芳新",16],["泯社稷之阽危兮君无与守","将正而毙兮谁善其后",17],["白云漠漠兮截洞口以为扃","轮鞅莫来兮无伤我清",18],["春秋冬夏风雨霜露无非教","胡为自古学者恁莫晓",19],["椎牛酾酒家家准拟犒六军","翠华不来冷落行宫门",20],["明年四斗三升之上更增科","三十六都之人将奈何",21],["又思天地之间固有足乐者","安得庄周之鹏穆王马",22],["罗浮高哉四百四十有二峰","三峰最高拔起金芙蓉",23],["我当吮笔和墨唤起文与可","把君画入李白杜甫图",24],["噫嚱人生万事大似茧抽缕","百绪千端无物不如许",25],["亦犹即绍圣以侮元祐之正","用大观以反崇宁之谲",26],["有时山空夜永斗柄出复没","眩眼千炬煜煜灯吐红",27],["呜呼参井之躔五十有六州","文风自古能与齐鲁侔",28],["殷盘周鼎愧君古人以相期","瓠壶呺然问字无一奇",29],["试问虎溪三士之乐如此不","霜寒夜永勿遣虚觥筹",30],["何如閙市里保寿面目全露","肉案头盘山自心密契",31],["明眼汉担拄杖绕天下横行","为什么透这些子不得",32],["缟衣玄裳兮横大海之惊涛","云旗先驱兮霓旌旖旎",33],["一祝吾侯早归绛阙佐明主","坐使天下风俗还真淳",34],["望松柏之苍苍兮我无令姿","岁寒之操兮炯炯心期",35],["北山崚嶒兮配井络之勋名","子孙绳绳兮聿彰厥声",36],["坦溪渺渺兮配流庆之深长","园林带宅兮风月无疆",37],["有美君子兮擥众芳而自饰","直哉惟清兮不亢不激",38],["故虽离朱莫覩其翼而善飞","䚦俞弗闻其声而工噬",39],["争似渔翁扁舟独往最脱洒","七十二峰相对长青青",40],["又如长虹百尺渴奔饮江罢","蜿蜒夭矫势欲凌青冥",41],["归来普请大众做个入门欢","是什么浙东山浙西水",42],["呜呼宇宙之大我辈未尝少","高歌一曲吾气其庶伸",43],["浩然先生不直内厩一疋马","可是蜀栈骑馿山路长",44],["丛林乡社有此俊迈之英才","我辈可老可死无余怀",45],["我不爱尔绝汉排云之健翼","爱尔秋来意气各有适",46],["力士嗔人譬如刀割大江水","世间闲是闲非皆如此",47],["前身曾作孔子孟子为人憎","也曾为禹为稷为人爱",48],["星岩高哉不知其几千丈兮","下有儒宫上接青云梯",49],["君持何术径往居此无百忧","便将天雷斧柄塞鬼穴",50],["闾阎府署得失已不挂齿颊","炼丹蜕骨又不形语言",51],["愿君志如莲濯淤泥而不染","操如竹拍霜雪而不零",52],["但能死生荣辱哀乐不能羁","存亡进退尽是无生路",53],["吾闻万物之精上浮为列星","天星之精堕地或为石",54],["嗟我安得力士赑屃如庚辰","一看公孙大娘浑脱舞",55],["知君尚方隃糜给使终有时","我独两鬓萧飒飞秋霜",56],["沈仲说父奉其高年之祖母","避喧却扫于此安晨昏",57],["坐致公卿贵人北面拜稽首","真人眼空四海瞪泬寥",58],["时哉好从檀溪踊跃起的卢","呼取黄熊赤豹来清都",59],["白衣苍狗须臾变化岂有定","乃在孝子方寸之中间",60],["呜呼明时才艺衮衮班集贤","安得有力贡之至尊前",61],["问之无㕮咀之剂针石之兵","惟有日两炊饭折足铛",62],["不如回去长安市上酒家眠","明日收拾东归理钓船",63],["自可等待天帝息怒解猜惑","依旧天上作伴同游戏",64],["缙山更在天南之南海树边","白发高堂岁晏惊寒早",65],["直须为侯濡豪沐椠纪循良","留待班马诸公亲纂录",66],["呜呼古之作者往往苦用心","岂惟杜预雅有春秋癖",67],["有时共谈三十六洞之秘笈","绿文赤字可以镌苍顽",68],["坎廪兮贫士失职而志不平","廓落兮羁旅而无友生",69],["浩然先生不直内厩一疋马","可是蜀栈骑驴山路长",70],["呜呼宇宙之大我辈未尝少","高歌一曲吾气其庶伸",71],["力士嗔人譬如刀割大江水","世间闲是闲非皆如此",72],["前身曾作孔子孟子为人憎","也曾为禹为稷为人爱",73],["但见崩城败郭惨淡照斜日","荒林故陇萧瑟凝寒烟",74],["蚤逢三光五岳之气乍分裂","天狼下地舐血流浑浑",75],["高崖铁锁不可攀援以径上","仰望白云楼观空峨巍",76],["乃谓仲尼颜子不死亦易事","忍见后天日月凋双丸",77],["托木石以为居兮青山为伍","鱼虾于侣兮鹿麋之友",78],["但可朝餐地炉所煨之紫芋","莫饮瓦瓮所酿之松花",79],["况有如貔如虎桓桓之将士","又有如鸳如鸾之英贤",80],["以足加腹兮忱故态之犹狂","廉贪立懦兮揭世之防",81],["重曰骥马千里兮扼于中道","塞草秋黄兮商飙浩浩",82],["维兹粟之茂实兮秀彼圆丘","异颖同茎兮琼粰翠英",83],["为问天公如何不肯暂时霁","得非怪我噤口不作诗",84],["骏兮骏兮安得复生一十二","为我扫除边警苏疮痍",85],["但愿清平老人百岁长无事","与君终日击壤歌康庄",86],["良乎良乎宁使尔画不直钱","无令后世好画兼好畋",87],["吾闻黄山三十六峰青插天","悬厓峭壁万丈飞流泉",88],["翻嗟古来才士芜没亦何限","感慨为尔击节生遥悲",89],["不如芒鞋竹杖游戏此山中","猿情鹤思千古流长谣",90],["邻里老翁怪我红颜未凋歇","前劝葡萄美酒玻璃觞",91],["此非摹我东溟无际之洪涛","胡为一轮初日停朱影",92],["鹿卢之蹻抟旋撇捩不遑息","神人绝顶为我开天门",93],["天子置之螭坳凤沼掌纶綍","袭以五色云霞文锦裾",94],["盘古以来二百二十馀万年","一一成败兴亡如指手",95],["九华仙人知我索寞遣汝至","不然我亦何计能寻招",96],["不知二气凝结抑是星所化","钟灵萃异特立无秋春",97],["安能龊龊苦恋五言七字长","吾伊如此读书读奚为",98],["辟如读书不读石鼓与丘坟","不知古人幻变突兀处",99],["云梯石磴之险不可以径上","仰见铁縆络石生寒光",100],["而置荒服于邦畿侯甸之安","纳民于安富尊荣之内",101],["答言每年晓起食粥方耕犁","今年耕犁晏归方食粥",102],["嗟嗟君去布袍蒯缑衿见肘","君归黄金紫印大如斗",103],["不有若翁费尽多心图百万","安能博得湖中一声好",104],["但愿年年月月日日饮酒时","尽如今年今月与今日",105],["须臾丰隆阿香左右总来到","驾风鞭霆飞过蓬莱岛",106],["我作歌词纪载混一全盛时","期与江山永永传无极",107],["但愿丹心不负青天与白日","青灯黄卷相对生虹霓",108],["况乎下有瀺灂万仞之洪淙","沧桑变幻兮人莫之穷",109],["邻里老翁怪我红颜未凋歇","前劝葡萄美酒玻璃觞",110],["左与右兮其皆溯日以为明","离日须臾兮月诚不可",111],["呜呼男儿万里远游志亦足","不尔蜗庐局蹜虚吾生",112],["杀妻的吴起倒挂了元帅印","顶灯的裴瑾挨些嘴巴",113],["教他爹乱了宫人制作着反","只这开手一着便不佳",113],["君曾饱看新安大好之山水","又曾驱车远度秦函殽",114],["闲取龙门百尺之桐斫绿绮","朝回解带便向书堂横",115],["不知金天之西何处得石砚","毋乃昆吾玉切新出硎",116],["呜呼国家多得袁氏父若子","安有四海金瓯破张李",117],["岂如黄山白岳千岁连理木","枝柯交错文采珊瑚殷",118],["石乎胡不含滋吐润惠四海","空存大骨尧尧学学然",119],["生不得当茂陵亦帝真龙子","乍可巫山峡月空婵娟",120],["傥与卢敖汗漫游戏太清上","安知我身前度非青莲",121],["吾闻太宗欲法文武增二弦","惜哉蔡裔所制今不传",122],["安得此月化作五色新诗筒","写我长离婉婉之心胸",123],["龙兮龙兮我愿招之复来入","神功既毕此堪蛰老屋",124],["欲求西北观瀑不险而绝奇","无若王官谷里天绅垂",125],["劝君慎秘此画勿为六丁取","王孙画马笔下空有神",126],["但愿三农年年大有乐租税","我亦坐拥砚田无恶岁",127],["大呼匡庐处士同去寻仙踪","振衣千仞长啸开群聋",128],["上有邝野王直职事之百司","下有陕西吕氏之一尼",129],["他日褒忠恤典大书烈士名","江宁府学廪生张继庚",130],["望中红白疏密向背不可数","仿佛身入流水天台间",131],["无奈娲皇日听笙簧谢不能","百神不敢言石言其事",132],["独惜南溟岛国尽隶他人属","坐叹热带之下无雄才",133],["此间山水清雄良足寄怀抱","且收倚天长剑韬神锋",134],["偶图山居志吾幸已脱劫外","乃劳翩然大句相推崇",134],["丈夫不作神仙亦当作豪杰","莫但留名万古将诗传",135],["何不学为鸾笙凤吹悦人耳","无乃造物赋尔偏多情",136],["诗人之笔隐显变化乃如此","岂与蛙吟蝉噪争申缩",137],["吾闻泰山之巅不可以走马","吕梁之壑不可以荡舟",138],["虽然无肴无酒不得谋一醉","犹有惊人好句同掀髯",139],["倘将四海之雾铢积寸算来","或尚不如伦敦城中雾",140],["尔时五羊仙城化作海上山","亦有四时之花开满悬",141],["嗟嗟人生穷通得失皆天成","何必纷纭车马去门庭",142],["莫五莫五保有斯湖借尔力","不独立马吴山一馋贼",143],["生不得当茂陵亦帝真龙子","乍可巫山峡月空婵娟",144],["每怜风自四山而下不见底","惟闻松声万壑寒飕飕",145],["寄谢无为老衲他日但过时","当为浮香主人留一宿",146]]});
